__NUXT_JSONP__("/sp", (function(a,b,c,d,e){return {data:[{$axios:{request:{},getUri:{},delete:{},get:{},head:{},options:{},post:{},put:{},patch:{},defaults:{headers:{common:{Accept:"application\u002Fjson, text\u002Fplain, *\u002F*","accept-encoding":"gzip, deflate"},delete:{},get:{},head:{},post:{"Content-Type":"application\u002Fx-www-form-urlencoded"},put:{"Content-Type":"application\u002Fx-www-form-urlencoded"},patch:{"Content-Type":"application\u002Fx-www-form-urlencoded"}},baseURL:"http:\u002F\u002Flocalhost:8000",transformRequest:[{}],transformResponse:[{}],timeout:0,adapter:{},xsrfCookieName:"XSRF-TOKEN",xsrfHeaderName:"X-XSRF-TOKEN",maxContentLength:-1,maxBodyLength:-1,validateStatus:{},transitional:{silentJSONParsing:true,forcedJSONParsing:true,clarifyTimeoutError:false}},interceptors:{request:{handlers:[{fulfilled:{},rejected:void 0,synchronous:false,runWhen:null}]},response:{handlers:[]}},CancelToken:{source:{}},isCancel:{},setBaseURL:{},setHeader:{},setToken:{},onRequest:{},onResponse:{},onRequestError:{},onResponseError:{},onError:{},create:{},$request:{},$delete:{},$get:{},$head:{},$options:{},$post:{},$put:{},$patch:{}},details:{slug:b,pageTitle:c,pageDescription:c,peopleChooseMli:{title:"3 Razones por las que la gente elige MLI",subtitle:"(Mentor Language Institute)",lists:[{image:"\u002Fimages\u002Fhome\u002Fsp\u002Fpeople-choose-mli-1.jpg",title:"Hollywood y Westwood",description:"Estamos ubicados en las mejores zonas de Los Ángeles. Los estudiantes no solo pueden estudiar inglés, sino también disfrutar de Los Ángeles.",read_more:[a]},{image:"\u002Fimages\u002Fhome\u002Fsp\u002Fpeople-choose-mli-2.jpg",title:"Clases por la mañana, tarde y noche",description:"Proporcionamos clases por la mañana, por la tarde o por la noche para las personas que necesitan horarios flexibles.",read_more:[a]},{image:"\u002Fimages\u002Fhome\u002Fsp\u002Fpeople-choose-mli-3.jpg",title:"$201 \u002F 1 semana",description:"Buena ubicación y precio razonable! Por favor compare nuestros precios con otras escuelas. Si desea información sobre la matrícula, haga click en Contáctenos a continuación.",read_more:[a]}]},highlyRated:"\u002Fimages\u002Fhome\u002Fsp\u002Fmli-highly-rated.jpg",courses:{title:"Cursos",lists:[{image:d,title:"Programa ESL",subtitle:["Este programa está compuesto por clases de escuchar\u002Fhablar, leer\u002Fvocabulario, y  gramática\u002Fescritura. El programa de ESL es ideal para estudiantes que desean mejorar sus habilidades generales de inglés."]},{image:e,title:"Programa TOEFL®",subtitle:["El programa TOEFL® de MLI es una mirada intensiva a las habilidades y estrategias necesarias para lograr un puntaje exitoso en las cuatro secciones de la Prueba basada en Internet (iBT)."]},{image:d,title:"Programa de Vacaciones ESL",subtitle:["Este programa se compone de clases de escucha\u002Fhabla, lectura\u002Fvocabulario y gramática\u002Fescritura. \u003Cbr\u003EOfrecemos el programa Vacation ESL para estudiantes que quieren estudiar inglés por un corto plazo."]},{image:e,title:"IELTS™",subtitle:["IELTS ™ es una prueba, desarrollada en el Reino Unido y Australia, para evaluar el dominio del inglés de los estudiantes. Recientemente, muchas universidades estadounidenses requieren un puntaje TOEFL® o un puntaje IELTS ™.","El programa consta de cuatro partes: escuchar, hablar, leer y escribir.","En esta clase, aprenderás las habilidades \u002F estrategias para lograr puntajes altos en cada sección.","Se dice que IELTS ™ es relativamente más fácil que TOEFL®.","Es un programa perfecto para estudiantes que encuentran TOEFL® difícil"]},{image:"\u002Fimages\u002Ficons\u002Fmessage.png",title:"Programa de conversación ",subtitle:["¡Nuestro programa se enfoca en mejorar sus habilidades de conversación en inglés a través de actividades interesantes y aprendizaje interactivo! En nuestras clases de conversación, los estudiantes explorarán una amplia gama de vocabulario, frases y expresiones idiomáticas que harán que sus conversaciones cobren vida. Practique su pronunciación en nuestra clase de CMAR. A través de discusiones divertidas, juegos de roles y actividades en grupo, ganará confianza para expresarse y participar en conversaciones significativas. Nuestros instructores experimentados le brindarán un ambiente de aprendizaje de apoyo, guiándole en un viaje de descubrimiento del idioma."]},{image:"\u002Fimages\u002Ficons\u002Fsuitcase.png",title:"Negocios + TOEIC®",subtitle:["El examen TOEIC® es un indicador del dominio del inglés en los negocios y lo utilizan diversas compañías y organizaciones de todo el mundo. Además del curso estándar de negocios, el curso TOEIC® prepara a los estudiantes para el éxito en el TOEIC® - Examen de lectura y escucha mediante la introducción de vocabulario esencial y estrategias de exploración para lograr un puntaje alto en el examen.","Este curso será útil para mejorar tus habilidades de inglés, como vocabulario, lectura, comprensión auditiva y gramática. Al aprender las estrategias para encontrar las respuestas correctas, podrás obtener una puntuación alta."]}]},schedule:"\u002Fimages\u002Fhome\u002Fsp\u002Ffree_trial_banner_sp.png",link:"\u002Fsp\u002Ffreetrial",partnerSchools:{title:"Universidades y Colegios Asociados a MLI",subtitle:"\"Los estudiantes de MLI pueden inscribirse en universidades o colegios asociados después de completar cierto nivel en los programas de MLI.\""},locationCampus:{title:"Ubicación \u002F Campus",lists:[{image:"\u002Fimages\u002Fhome\u002Flocation-campus-1.jpg",title:"Westwood Campus",subtitle:"Westwood es un barrio vibrante y único ubicado en el lado oeste de Los Ángeles. Westwood es famoso por ser el hogar de UCLA.",read_more:["\u003Ca href=\"\u002Fsp\u002Fwestwood\u002F\"\u003E» LEER MAS\u003C\u002Fa\u003E"]},{image:"\u002Fimages\u002Fhome\u002Flocation-campus-2.jpg",title:"Hollywood Campus",subtitle:"El campus de Hollywood está muy cerca del famoso Teatro Chino. Hay cines famosos, buenos restaurantes, tiendas y clubes en el área de Hollywood y esta zona siempre es un lugar muy animado.",read_more:["\u003Ca href=\"\u002Fsp\u002Fhollywood\u002F\"\u003E» LEER MAS\u003C\u002Fa\u003E"]}]},testimonials:{title:"Testimonios de estudiantes",seemoreBtn:"Ver más",TestimonialLink:"\u002Fsp\u002Ftestimonials",readmoreBtn:"Leer más"},dir:"\u002Fhome",path:"\u002Fhome\u002Fsp",extension:".json",createdAt:"2026-10-22T16:31:29.613Z",updatedAt:"2025-05-26T12:06:27.786Z"},lang:b}],fetch:{},mutations:void 0}}("\u003Ca href=\"\u002Fsp\u002Ffeature\u002F\"\u003E» LEER MAS\u003C\u002Fa\u003E","sp","Escuela de Inglés en Los Angeles con excelente precio-calidad | Mentor Language Institute","\u002Fimages\u002Ficons\u002Fpaste.png","\u002Fimages\u002Ficons\u002Fpen.png")));